-- Import of Katherine's 27 Sep–03 Oct 2026 weekly workbook, with source rows retained.
create table private.availability_import_rows (
  batch_sha256 text not null,
  source_row integer not null,
  asset_id uuid references public.inventory_assets(id),
  code text not null,
  source jsonb not null,
  imported_at timestamptz not null default now(),
  primary key (batch_sha256, source_row)
);
alter table private.availability_import_rows enable row level security;
revoke all on private.availability_import_rows from public, anon, authenticated;

alter table public.inventory_assets add column availability_source_batch text;
alter table public.availability_entries add column advisor_source_label text
  check (advisor_source_label is null or length(btrim(advisor_source_label)) between 1 and 200);

