insert into private.availability_import_rows(batch_sha256, source_row, asset_id, code, source)
select '30B66DBF47FFA1D560C62981495DFBE166DD5DD5A3BBBB95990C87C677F15F5B', (source->>'row')::integer, a.id, source->>'code', source
  from rows left join public.inventory_assets a
    on regexp_replace(upper(a.canonical_code),'[^A-Z0-9]','','g') =
       regexp_replace(upper(source->>'code'),'[^A-Z0-9]','','g');

do $$
declare matched_count integer;
begin
  select count(*) into matched_count from private.availability_import_rows
   where batch_sha256='30B66DBF47FFA1D560C62981495DFBE166DD5DD5A3BBBB95990C87C677F15F5B' and asset_id is not null;
  if matched_count <> 85 then raise exception 'Expected 85 matched catalog assets, got %', matched_count; end if;
  if (select count(*) from public.availability_entries where status='active') <> 1
     or not exists (select 1 from public.availability_entries
       where id='8b113dac-6d6c-4330-be13-cb16664ffa48' and status='active'
         and asset_id=(select id from public.inventory_assets where canonical_code='APT-005')) then
    raise exception 'Availability changed since source reconciliation';
  end if;
end $$;

-- The user confirmed the workbook's APT-005 available state over the old
-- clientless occupancy. Keep its history as cancelled.
update public.availability_entries
   set status='cancelled', reason='Conciliación Excel semanal 27/09-03/10/2026: APT-005 disponible',
       revision=revision+1, updated_at=now(),
       updated_by='1de1af59-a4e3-4ff6-9427-3392ffb39c27'
 where id='8b113dac-6d6c-4330-be13-cb16664ffa48' and status='active';

-- All 85 currently offered assets are present in the supplied weekly sheet.
-- An undated rental and three non-offerable statuses stay blocked.
update public.inventory_assets a
   set availability_review_required=false,
       availability_source_batch='30B66DBF47FFA1D560C62981495DFBE166DD5DD5A3BBBB95990C87C677F15F5B',
       operational=case when r.source->>'state' in
         ('RENTada con el dueño de terreno','SALE DEL DISPONIBLE','disponible verificaR ANGI')
         or (r.source->>'state'='ARRENDADA' and (r.source->>'start' is null or r.source->>'end' is null))
         then 'unavailable' else 'operational' end
  from private.availability_import_rows r
 where r.batch_sha256='30B66DBF47FFA1D560C62981495DFBE166DD5DD5A3BBBB95990C87C677F15F5B' and r.asset_id=a.id;

-- Even if a row says DISPONIBLE, an overlapping dated client commitment is
-- kept occupied until its stated end date to avoid offering the same days twice.
insert into public.availability_entries(
  asset_id, starts_on, ends_on, kind, status, reason, evidence_reference,
  customer_name, campaign_name, advisor_source_label, created_by, updated_by
)
select r.asset_id, (r.source->>'start')::date, (r.source->>'end')::date,
       'reservation', 'active',
       case when r.source->>'state'='DISPONIBLE'
            then 'Excel semanal: disponible con cliente y fechas aún vigentes; se conserva ocupación hasta fin indicado'
            else 'Arrendada según Excel semanal 27/09-03/10/2026' end,
       'Excel Katherine 27/09-03/10/2026, hoja 2, fila ' || r.source_row,
       nullif(btrim(r.source->>'customer'),''),
       nullif(btrim(r.source->>'campaign'),''),
       nullif(btrim(r.source->>'advisor'),''),
       '1de1af59-a4e3-4ff6-9427-3392ffb39c27',
       '1de1af59-a4e3-4ff6-9427-3392ffb39c27'
  from private.availability_import_rows r
 where r.batch_sha256='30B66DBF47FFA1D560C62981495DFBE166DD5DD5A3BBBB95990C87C677F15F5B' and r.asset_id is not null
   and r.source->>'start' is not null and r.source->>'end' is not null
   and (r.source->>'end')::date >= '2026-10-01'
   and r.source->>'state' in ('ARRENDADA','DISPONIBLE');

create or replace function private.sales_availability_assignments_v2(p_start date, p_end date)
returns table(asset_id uuid, starts_on date, ends_on date, state text,
  customer_name text, campaign_name text, advisor_id uuid, advisor_name text)
language plpgsql security definer set search_path = '' as $$
declare today_bogota date := (clock_timestamp() at time zone 'America/Bogota')::date;
begin
  if (select auth.uid()) is null or not (
    private.has_permission('cotizador.availability.reserve')
    or private.has_permission('cotizador.availability.manage')
  ) then raise exception 'Availability permission required' using errcode = '42501'; end if;
  if p_start is null or p_end is null or not isfinite(p_start) or not isfinite(p_end)
     or p_start < today_bogota or p_end < p_start or p_end - p_start > 365 then
    raise exception 'Invalid assignment interval' using errcode = '22023';
  end if;
  return query
  select e.asset_id, e.starts_on, e.ends_on,
         case when e.kind in ('hold','manual_reservation') then 'reservada' else 'ocupada' end,
         coalesce(e.customer_name, q.customer_snapshot->>'name'),
         e.campaign_name, e.advisor_id,
         coalesce(case when advisor.display_name = 'Usuario invitado'
              then coalesce(advisor_auth.email::text, advisor.display_name)
              else advisor.display_name end, e.advisor_source_label)
    from public.availability_entries e
    join public.inventory_assets a on a.id = e.asset_id
    left join public.quotes q on q.id = e.quote_id
    left join public.profiles advisor on advisor.id = e.advisor_id
    left join auth.users advisor_auth on advisor_auth.id = e.advisor_id
   where e.status = 'active' and e.kind in ('hold','manual_reservation','reservation')
     and (e.kind <> 'hold' or e.expires_at > clock_timestamp())
     and e.starts_on <= p_end and e.ends_on >= p_start
     and a.lifecycle = 'active' and a.visibility = 'visible'
     and not a.is_provisional and a.booking_mode = 'exclusive_daily'
   order by e.ends_on, a.canonical_code limit 500;
end;
$$;

create function private.sales_availability_commercial_facts()
returns table(asset_id uuid, source_state text, rent_price numeric, agency_price_2026 numeric, source_row integer)
language plpgsql security definer set search_path = '' as $$
begin
  if (select auth.uid()) is null or not (
    private.has_permission('cotizador.availability.reserve')
    or private.has_permission('cotizador.availability.manage')
  ) then raise exception 'Availability permission required' using errcode = '42501'; end if;
  return query
  select r.asset_id, r.source->>'state',
         case when r.source->>'price_month' ~ '^[0-9]+(\.[0-9]+)?$' then (r.source->>'price_month')::numeric end,
         case when r.source->>'price_2026' ~ '^[0-9]+(\.[0-9]+)?$' then (r.source->>'price_2026')::numeric end,
         r.source_row
    from private.availability_import_rows r
    join public.inventory_assets a on a.id=r.asset_id and a.availability_source_batch=r.batch_sha256
   where r.batch_sha256='30B66DBF47FFA1D560C62981495DFBE166DD5DD5A3BBBB95990C87C677F15F5B';
end;
$$;
create function public.sales_availability_commercial_facts()
returns table(asset_id uuid, source_state text, rent_price numeric, agency_price_2026 numeric, source_row integer)
language sql security invoker set search_path = '' as $$
  select * from private.sales_availability_commercial_facts();
$$;
revoke all on function private.sales_availability_commercial_facts(),
  public.sales_availability_commercial_facts() from public, anon, authenticated;
grant execute on function private.sales_availability_commercial_facts(),
  public.sales_availability_commercial_facts() to authenticated;
